simple_token = apis.simple_note.login(username='deniseburch@gmail.com', password=super_pw['simple_note'])['access_token']

def fetch_notes(query, page_limit=20):
    page_index=0
    all_notes=[]
    while True:
        resp = apis.simple_note.search_notes(access_token=simple_token, query=query, page_index=page_index, page_limit=page_limit)
        if isinstance(resp, dict):
            notes = resp.get('notes') or resp.get('results') or []
        else:
            notes = resp
        if not notes:
            break
        all_notes.extend(notes)
        if len(notes)<page_limit:
            break
        page_index+=1
    return all_notes

for q in ['amazon', 'Amazon', 'amazon shopping', 'shopping list', 'cart', 'wish list']:
    notes = fetch_notes(q)
    filtered=[n for n in notes if 'amazon' in n.get('title','').lower() or 'shop' in n.get('title','').lower() or 'cart' in n.get('title','').lower()]
    print('\nQUERY',q,'returned',len(notes),'filtered',len(filtered))
    print([(n['note_id'], n['title'], n.get('tags')) for n in filtered[:10]])

